mapper.sql:
WHERE l.deleted=0
AND (l.contract_code LIKE CONCAT('%', #{search}, '%') OR l.ad_location LIKE CONCAT('%', #{search}, '%') OR l.ad_position_code LIKE CONCAT('%', #{search}, '%'))
AND l.lessee_company LIKE CONCAT('%', #{lesseeCompany}, '%') AND l.approval_status = #{approvalStatus}

mapper.select:
SELECT COUNT(*) FROM t_ad_lease_detail
WHERE ad_position_code=#{adPositionCode} AND deleted=0 AND approval_status='APPROVED'
  AND lease_start_date <= #{leaseEndDate} AND lease_end_date >= #{leaseStartDate}
AND ad_lease_id != #{excludeLeaseId}
